    "access": "off",
    "luck": [{"chance": 10, "cost": 1000}, {"chance": 20, "cost": 1800}, {"chance": 30, "cost": 2800},
             {"chance": 40, "cost": 4000}, {"chance": 50, "cost": 5500}, {"chance": 60, "cost": 7200},
