    "offline": [{"perHour": 2, "cost": 100}, {"perHour": 4, "cost": 175}, {"perHour": 6, "cost": 263},
                {"perHour": 8, "cost": 375}, {"perHour": 10, "cost": 500}, {"perHour": 12, "cost": 650},
                {"perHour": 14, "cost": 825}, {"perHour": 16, "cost": 1025}, {"perHour": 18, "cost": 1250},
